package body twiddle_dif_q1_14_pkg is

    function get_twiddle(stage, butterfly, size : natural) return complex_q1_14 is
        variable twiddle_index : natural;
    begin       
        twiddle_index := butterfly * (2**stage);
        
        -- Safety check to stay within the 0-31 range
        if twiddle_index >= (size/2) then
            return (re => to_signed(16384,16), im => to_signed(0,16)); -- Return 1.0
        else
            case size is
                when 2 => return TWIDDLE_2(twiddle_index);
                when 4 => return TWIDDLE_4(twiddle_index);
                when 8 => return TWIDDLE_8(twiddle_index);
                when 16 => return TWIDDLE_16(twiddle_index);
                when 32 => return TWIDDLE_32(twiddle_index);
                when 64 => return TWIDDLE_64(twiddle_index);
                when 128 => return TWIDDLE_128(twiddle_index);
                when 256 => return TWIDDLE_256(twiddle_index);
                when 512 => return TWIDDLE_512(twiddle_index);
                when 1024 => return TWIDDLE_1024(twiddle_index);
                when 2048 => return TWIDDLE_2048(twiddle_index);
                -- when 4096 => return TWIDDLE_4096(twiddle_index);
                -- when 8192 => return TWIDDLE_8192(twiddle_index);
                when others => null;
            end case;
        end if;
    end function;

end package body;